// Extract query and context
const query = $json.body.query || $json.query || '';
const conversationId = $json.body.conversationId || $json.conversationId || '';

return {
  json: {
    query,
    conversationId
  }
};

// Build prompt for intent classification
const query = $json.query;
const context = $node['Get Conversation Context'].json.context || {};
const recentQueries = context.messages?.slice(-3).map(m => m.text).join('\n') || 'None';

const prompt = `You are an intent classifier for a railway documentation chatbot. Analyze the user query and classify it into one of these intents:

**ASK**: User wants a direct answer to a specific question (e.g., "What are the brake procedures?", "How do I configure VLAN?")
**SEARCH**: User wants to find relevant documents without a generated answer (e.g., "Find documents about safety", "Show me Class 395 manuals")

Recent conversation context:
${recentQueries}

Current query: "${query}"

Respond ONLY with a JSON object in this exact format:
{
  "intent": "ASK" or "SEARCH",
  "confidence": 0.0 to 1.0,
  "reasoning": "Brief explanation"
}

JSON response:`;

return {
  json: {
    prompt,
    query,
    conversationId: $json.conversationId
  }
};

// Parse Ollama response and extract intent
const ollamaResponse = $json.response || '';
let intent = 'ASK'; // default
let confidence = 0.7;
let reasoning = 'Default classification';

try {
  // Try to extract JSON from response
  const jsonMatch = ollamaResponse.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    intent = parsed.intent || 'ASK';
    confidence = parsed.confidence || 0.7;
    reasoning = parsed.reasoning || 'LLM classification';
  } else {
    // Fallback: simple keyword detection
    const queryLower = $node['Parse Input'].json.query.toLowerCase();
    if (queryLower.includes('find') || queryLower.includes('search') || queryLower.includes('show me') || queryLower.includes('list')) {
      intent = 'SEARCH';
      confidence = 0.6;
      reasoning = 'Keyword-based fallback';
    }
  }
} catch (e) {
  // Use fallback
  const queryLower = $node['Parse Input'].json.query.toLowerCase();
  if (queryLower.includes('find') || queryLower.includes('search') || queryLower.includes('show me') || queryLower.includes('list')) {
    intent = 'SEARCH';
  }
  confidence = 0.5;
  reasoning = 'Parsing error, using fallback';
}

return {
  json: {
    query: $node['Parse Input'].json.query,
    conversationId: $node['Parse Input'].json.conversationId,
    intent,
    confidence,
    reasoning
  }
};
